import { transform } from "esbuild";
import { writeFile } from "node:fs/promises";

const SOURCE = `export function computeTotal(items) {
  let total = 0;
  for (const item of items) {
    if (item.price < 0) {
      throw new RangeError("negative price");
    }
    total += item.price * item.quantity;
  }
  return total;
}
`;

const result = await transform(SOURCE, {
  minify: true,
  sourcemap: true,
  sourcefile: "src/checkout.ts",
  loader: "ts",
});

const file = `/**
 * GENERATED by e2e/gen-map-fixture.mjs. Do not edit by hand.
 *
 * A real esbuild-minified bundle and its source map. Used to test the VLQ
 * decoder against output a bundler actually produces.
 */

export const MINIFIED = ${JSON.stringify(result.code)};

export const SOURCE_MAP = ${JSON.stringify(JSON.parse(result.map), null, 2)};
`;
await writeFile(new URL("../src/sourcemaps/map-fixture.ts", import.meta.url), file);
console.log("wrote map-fixture.ts");
console.log("minified:", result.code.slice(0, 120));
